INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('산나이마루야마 유적', '三内丸山遺跡', 'HISTORIC', '青森県', '青森市', 40.811500, 140.696600, 'FIXED', '09:00', '17:00', NULL, '6/1~9/30·골든위크는 18:00까지. 입장 30분 전 마감. 매월 넷째 월요일(공휴일이면 다음 날)·12/30~1/1 휴관', '500엔 (대학생 250엔, 고교생 이하 무료. 특별전 별도)', '대형 굴립주 건물과 수혈 주거가 복원된 조몬 시대 대규모 마을 유적. 2021년 "홋카이도·북도호쿠 조몬 유적군"으로 세계유산에 올랐다.', '가이던스 시설 조몬지유칸에서 토기·토우를 보고, 토우 만들기 같은 체험도 할 수 있다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('네부타의 집 와랏세', 'ねぶたの家 ワ・ラッセ', 'MUSEUM', '青森県', '青森市', 40.829000, 140.735500, 'FIXED', '09:00', '18:00', NULL, '5~8월은 19:00까지. 입장 30분 전 마감. 8/9·8/10(전시 교체), 12/31·1/1 휴관', '620엔 (고교생 460엔, 초중학생 260엔)', 'JR 아오모리역 바로 앞, 실제 축제에 나간 대형 네부타 4대를 상설 전시하는 시설. 2층 네부타 뮤지엄에서 축제의 기원과 제작 기술을 소개한다.', '하루 몇 차례(11:10·13:10·15:10·17:10, 각 20분) 하야시 생연주와 하네토 체험이 있다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('아오모리 현립미술관', '青森県立美術館', 'MUSEUM', '青森県', '青森市', 40.814300, 140.689500, 'FIXED', '09:30', '17:00', NULL, '입관 16:30까지. 둘째·넷째 월요일(공휴일이면 다음 날) 휴관', '컬렉션전 700엔 (대학생 400엔, 고교생 이하 무료. 기획전 별도)', '산나이마루야마 유적에서 착상해 설계한 미술관. 무나카타 시코, 나라 요시토모 등 아오모리 출신 작가 작품이 있고, 높이 약 8.5m의 "아오모리 개"가 상징이다.', '산나이마루야마 유적과 붙어 있어 같이 돌기 좋다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('후루카와 시장 (아오모리 교사이 센터)', '青森魚菜センター', 'MARKET', '青森県', '青森市', 40.825700, 140.739600, 'FIXED', '07:00', '16:00', 'TUE', '놋케동 기준, 밥이 떨어지면 종료. 골든위크·네부타 축제·오봉·연말연시엔 휴일이 바뀔 수 있음', '무료 (놋케동 식권 별도)', '자기가 고른 회를 밥에 올려 먹는 "놋케동"의 발상지. 무쓰만에서 잡은 가리비 등 신선한 해산물 가게 약 25곳이 모여 있다.', '식권을 사서 가게를 돌며 재료를 고르는 방식이고, 놋케동은 시장 안 휴게소에서 먹어야 한다. 카드 불가.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('센슈 공원 (구보타성 터)', '千秋公園', 'PARK_GARDEN', '秋田県', '秋田市', 39.722500, 140.125900, 'ALWAYS', NULL, NULL, NULL, '공원은 24시간. 오스미야구라는 9:00~16:30, 12/1~3/31 휴관', '무료 (오스미야구라 150엔)', '아키타 번주 사타케 가문의 거성 구보타성 터에 만든 공원. 복원한 오스미야구라 전망실에서 시내가 내려다보인다.', '봄엔 약 700그루 벚꽃의 명소로 "센슈 공원 벚꽃 축제"가 열린다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('아키타 시민시장', '秋田市民市場', 'MARKET', '秋田県', '秋田市', 39.716900, 140.130600, 'FIXED', '05:00', '18:00', 'SUN', '가게마다 시간이 다름', '무료', '신선한 생선·채소·과일과 잡화점까지 약 50개 가게가 모인 "아키타 시민의 부엌".', '밥을 사서 가게를 돌며 반찬을 얹는 놋케동이 있고, 시장 직영 회전초밥집도 있다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('네부리나가시관 (민속예능전승관)', '秋田市民俗芸能伝承館', 'MUSEUM', '秋田県', '秋田市', 39.721900, 140.117400, 'FIXED', '09:30', '16:30', NULL, '12/29~1/3 휴관', '130엔 (고교생 이하 무료)', '간토 마쓰리를 비롯한 아키타의 전통 행사와 민속예능 자료를 전시하는 시설.', '간토 연기 시연이 있고 직접 들어 보는 체험 코너도 있다. 옆 옛 가네코가 주택도 같은 입장권으로 볼 수 있다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('나마하게관', 'なまはげ館', 'MUSEUM', '秋田県', '男鹿市', 39.937300, 139.795800, 'FIXED', '08:30', '17:00', NULL, '연중무휴', '660엔 (오가 신잔 전승관 공통권 1,100엔)', '오가 각 지구에서 쓰던 다양한 나마하게 탈과 의상을 실물 전시하는 시설. 나마하게 행사는 유네스코 무형문화유산이다.', '옆 오가 신잔 전승관에서는 초가집에서 나마하게 행사를 재현하는 실연을 볼 수 있다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('오가 수족관 GAO', '男鹿水族館GAO', 'AMUSEMENT', '秋田県', '男鹿市', 39.938900, 139.712800, 'FIXED', '09:00', '17:00', NULL, '최종 입관 16:00. 계절에 따라 시간이 바뀌고 휴관일은 공식 확인', '1,300엔 (초중학생 500엔)', '동해에 맞닿은 수족관. 약 40종 2,000마리가 헤엄치는 "오가의 바다 대수조"와 북극곰이 인기다.', '아키타 현어 도루묵을 소개하는 "하타하타 박물관"도 있다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('뉴도자키', '入道崎', 'VIEWPOINT', '秋田県', '男鹿市', 40.005700, 139.701000, 'ALWAYS', NULL, NULL, NULL, '상시 개방. 뉴도사키 등대 내부는 4월 하순~11월 상순 9:00~16:00', '무료 (등대 300엔)', '북위 40도선 위에 있는 오가반도 최북단 곶. 잔디밭 끝에 높이 30m 절벽과 동해가 펼쳐진다.', '흑백 줄무늬 등대는 전국 16곳뿐인 올라갈 수 있는 등대 중 하나다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('가마쿠라관', '横手市ふれあいセンター かまくら館', 'MUSEUM', '秋田県', '横手市', 39.310800, 140.555200, 'FIXED', '09:00', '17:00', NULL, '12/29~1/3 휴관, 임시 휴관 있음', '100엔 (요코테 공원 전망대 등 4관 공통, 중학생 이하 무료)', '영하 10도로 유지되는 방에 진짜 눈으로 만든 가마쿠라를 1년 내내 전시하는 시설.', '"돈부쿠"라는 솜옷을 빌려 입고 가마쿠라에 들어가 볼 수 있다. 매점엔 요코테 야키소바 관련 상품이 많다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('요코테 공원 전망대 (요코테성)', '横手公園展望台', 'VIEWPOINT', '秋田県', '横手市', 39.312700, 140.567300, 'FIXED', '09:00', '16:30', NULL, '4/1~11/30 개관. 12~3월 휴관(2월 중순 눈 축제 때 임시 개관)', '100엔 (4관 공통, 중학생 이하 무료)', '요코테성 니노마루 터에 1965년 세운 천수각 모양 전망대. 4층 전망실에서 요코테 분지와 조카이산이 보이고, 1~3층은 향토자료관이다.', '봄엔 벚꽃 축제, 2월엔 가마쿠라 불빛을 보러 가기 좋다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('야마데라 (릿샤쿠지)', '立石寺', 'SHRINE_TEMPLE', '山形県', '山形市', 38.312800, 140.437500, 'FIXED', '08:00', '17:00', NULL, '연중무휴', '입산료 500엔 (4세~초등학생 200엔)', '860년 지카쿠 대사가 연 천태종 절. 산문에서 오쿠노인까지 1,015단 돌계단을 오르며 번뇌가 사라진다고 전한다.', '왕복 1~2시간쯤 걸리니 운동화가 좋다. 산기슭 근본중당엔 1,000년 넘게 꺼지지 않은 "불멸의 법등"이 있다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('가조 공원 (야마가타성 터)', '霞城公園', 'PARK_GARDEN', '山形県', '山形市', 38.253300, 140.327200, 'FIXED', '05:00', '22:00', NULL, '4~10월 기준, 11~3월은 5:30부터. 연중무휴', '무료', '야마가타성 혼마루·니노마루 터를 정비한 약 35.9ha 공원. 복원한 니노마루 히가시오테몬과 성주 모가미 요시아키 기마상이 있다.', '봄엔 약 1,500그루 벚꽃이 피고 야간 조명도 한다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('분쇼칸 (야마가타현 향토관)', '文翔館', 'HISTORIC', '山形県', '山形市', 38.256400, 140.338600, 'FIXED', '09:00', '16:30', NULL, '첫째·셋째 월요일(공휴일이면 다음 날), 12/29~1/3 휴관', '무료', '1916년에 지은 영국 근세 부흥 양식의 옛 현청사·현의회 의사당. 국가 중요문화재다.', '시계탑 시계는 현재 가동 중인 것 중 삿포로 시계탑 다음으로 오래됐다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('즈이호덴', '瑞鳳殿', 'HISTORIC', '宮城県', '仙台市青葉区', 38.252100, 140.879800, 'FIXED', '09:00', '16:50', NULL, '2/1~11/30 기준, 12/1~1/31은 16:20까지. 입관 20분 전 마감', '570엔 (고교생 410엔, 초중학생 210엔)', '센다이 번조 다테 마사무네의 영묘. 1945년 공습으로 불탄 뒤 1979년에 재건했고, 모모야마 양식의 화려한 장식이 볼거리다.', NULL, NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('센다이성 터 (아오바성)', '仙台城跡', 'HISTORIC', '宮城県', '仙台市青葉区', 38.252900, 140.856000, 'ALWAYS', NULL, NULL, NULL, '24시간 출입 가능. 센다이성 견문관은 9:00~17:00', '무료', '다테 마사무네가 쌓은 성의 터. 혼마루 터에 다테 마사무네 기마상이 있고, 맑은 날엔 센다이 시내와 태평양까지 보인다.', '해 진 뒤 23시까지 석벽과 기마상에 조명을 비춘다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('오사키 하치만구', '大崎八幡宮', 'SHRINE_TEMPLE', '宮城県', '仙台市青葉区', 38.271900, 140.845100, 'VARIES', NULL, NULL, NULL, '외관 견학 자유', '무료', '1607년 다테 마사무네가 세운 센다이의 총진수. 화려한 모모야마 양식 사전은 국보다.', '1월 14일 "마쓰타키마쓰리(돈토사이)" 때는 정월 장식을 태우는 불에 많은 참배객이 모인다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('센다이 아침시장', '仙台朝市', 'MARKET', '宮城県', '仙台市青葉区', 38.258800, 140.878700, 'FIXED', '08:00', '17:00', 'SUN', '공휴일·오봉(3일)·1/1~1/4 휴무, 가게마다 다름', '무료', '센다이역에서 걸어서 5분 거리의 "센다이의 부엌". 생선·채소·과일 가게가 늘어선다.', '고로케, 해산물 덮밥, 즌다 경단 같은 먹거리를 걸어 다니며 먹기 좋다.', NULL, NULL, DATE '2026-11-22', NULL);
